mapper.sql:
WHERE h.DELETED_YN = 'N' AND EXISTS ( SELECT 1 FROM SALES_ORDER_LINE active_line WHERE active_line.SALES_ORDER_ID = h.SALES_ORDER_ID AND active_line.DELETED_YN = 'N' )
AND h.PROGRESS_STATUS = #{progressStatus}
AND ( UPPER(h.SALES_ORDER_NO) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR TO_CHAR(h.BUSINESS_DATE, 'YYYY/MM/DD') LIKE '%' || #{criteria.keyword} || '%' OR UPPER(h.PARTNER_NAME) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR UPPER(h.ASSIGNEE_NAME) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR EXISTS ( SELECT 1 FROM SALES_ORDER_LINE search_line LEFT JOIN ITEM search_item ON search_item.ITEM_ID = search_line.ITEM_ID WHERE search_line.SALES_ORDER_ID = h.SALES_ORDER_ID AND search_line.DELETED_YN = 'N' AND ( UPPER(search_item.ITEM_CODE) LIKE '%' || UPPER(#{criteria.keyword}) || '%' OR UPPER(search_line.ITEM_NAME) LIKE '%' || UPPER(#{criteria.keyword}) || '%' ) ) )
